text:
{
 "reason": {
  "es": "この法律《ほうりつ》の案《あん》を出《だ》した衆議院《しゅうぎいん》の議院運営委員会《ぎいんうんえいいいんかい》は、こう説明《せつめい》しています。国《くに》の公務員《こうむいん》などの旅費《りょひ》（仕事《しごと》で出《で》かけるときのお金《かね》）についての法律《ほうりつ》が変《か》わりました。それにあわせて、国会《こっかい》によばれる証人《しょうにん》などの旅費《りょひ》と日当《にっとう》（1日《にち》ごとにはらうお金《かね》）について、きまりをととのえる必要《ひつよう》があるため、としています。",
  "hs": "法律案を提出した衆議院議院運営委員会は、国家公務員等の旅費に関する法律の改正に伴《ともな》い、議院に出頭する証人などの旅費と日当（1日ごとに支払《しはら》うお金）について規定を整理する必要があるためとしている。",
  "std": "法律案を提出した衆議院議院運営委員会は、国家公務員等の旅費に関する法律の改正に伴い、議院に出頭する証人等の旅費及び日当について規定を整理する必要があるためとしている。",
  "univ": "法律案を起草・提出した衆議院議院運営委員会は、国家公務員等の旅費に関する法律の改正に伴い、証人等の旅費及び日当について整理する必要があるためとしている。"
 },
 "who": {
  "es": "衆議院《しゅうぎいん》や参議院《さんぎいん》によばれて出《で》ていく、証人《しょうにん》などです。旅費《りょひ》や日当《にっとう》の受《う》け取《と》り方《かた》が変《か》わります。また、旅費《りょひ》の種類《しゅるい》や中身《なかみ》を話《はな》し合《あ》って決《き》める、両方《りょうほう》の議院《ぎいん》の議長《ぎちょう》も関係《かんけい》します。",
  "hs": "議院に出頭する（よばれて出向く）証人など（旅費・日当を受け取る人）と、旅費の種目と内容を協議して定める両議院の議長。",
  "std": "議院に出頭する証人等（旅費・日当の支給を受ける者）、旅費の種目と内容を協議して定める両議院の議長。",
  "univ": "議院に出頭する証人等（旅費及び日当の支給を受ける者）、旅費の種目及び内容を協議して定める両議院の議長。"
 },
 "committee": {
  "es": "この法律《ほうりつ》の案《あん》は、3月《がつ》18日《にち》に、衆議院《しゅうぎいん》の議院運営委員会《ぎいんうんえいいいんかい》がつくって出《だ》したものです。参議院《さんぎいん》では、議院運営委員会《ぎいんうんえいいいんかい》が話《はな》し合《あ》いました。決《けつ》をとった結果《けっか》、全員《ぜんいん》が賛成《さんせい》し、そのまま通《とお》すことに決《き》まりました。",
  "hs": "この法律案は、3月18日に衆議院議院運営委員会が起草し（案文をつくり）、提出したものである。参議院議院運営委員会では、採決の結果、全会一致《ぜんかいいっち》で原案どおり可決すべきものとした。",
  "std": "本法律案は、3月18日に衆議院議院運営委員会が起草し、提出したもの。参議院議院運営委員会では、採決の結果、全会一致で原案どおり可決すべきものとした。",
  "univ": "本法律案は、3月18日、衆議院議院運営委員会において起草し、提出したものである。参議院議院運営委員会においては、採決の結果、本法律案は全会一致をもって原案どおり可決すべきものと決定した。"
 },
